91	 */
92	export interface RegistrarClient {
93	  /** DB/dispatch id — e.g. "namecom", "namecheap". Never shown to a customer. */
94	  readonly id: string;
95	  /** Admin-display-only human name — e.g. "name.com", "Namecheap". NEVER pass to a customer-facing function or string. */
96	  readonly label: string;
97	
98	  /** Are this registrar's credentials present in the environment? */
99	  configured(): boolean;
100	
101	  checkDomains(domains: string[]): Promise<DomainCheck[]>;
102	  registerDomain(
103	    domain: string,
104	    years: number,
105	    contact: RegistrantContact,
106	    purchaseCents: number
107	  ): Promise<{ expiresAt?: Date }>;
108	  renewDomain(domain: string, years: number, purchaseCents: number): Promise<void>;
109	  domainInfo(domain: string): Promise<{ expires?: Date; created?: Date }>;
110	  /**
111	   * Disable the REGISTRAR'S OWN auto-renew flag on a just-registered/renewed
112	   * domain (see `lib/registrar.ts`'s doc comment on the name.com equivalent for
113	   * why this matters — a registrar renewing independently on its own schedule
114	   * would charge Nxeon's reseller balance regardless of the customer's choice).
115	   * Best-effort: must never throw in a way that unwinds an already-successful
116	   * registration/renewal.
117	   */
118	  disableRegistrarAutorenew(domain: string): Promise<void>;
119	
120	  // ---- Nameservers / registrar lock / outbound-transfer auth code ----
121	  setNameservers(domain: string, nameservers: string[]): Promise<void>;
122	  lockDomain(domain: string): Promise<void>;
123	  unlockDomain(domain: string): Promise<void>;
124	  isDomainLocked(domain: string): Promise<boolean>;
125	  /** EPP/auth code for an outbound transfer. Null when the registrar has none to give. */
126	  getAuthCode(domain: string): Promise<string | null>;
127	
128	  // ---- Inbound transfers (transfer-in) ----
129	  checkTransfer(domain: string): Promise<TransferCheck>;
130	  createTransfer(domain: string, authCode: string, purchaseCents: number): Promise<TransferInfo>;
131	  getTransfer(domain: string, startedAt?: Date | null): Promise<TransferInfo | null>;
132	  cancelTransfer(domain: string): Promise<TransferInfo>;
133	  /** All inbound transfers on this registrar's account (ops/debug — not used per-domain). */
134	  listTransfers(): Promise<TransferInfo[]>;
135	
136	  // ---- DNS ----
137	  listRecords(domain: string): Promise<DnsRecord[]>;
138	  addRecord(
139	    domain: string,
140	    rec: { host: string; type: string; answer: string; ttl?: number; priority?: number }
141	  ): Promise<void>;
142	  deleteRecord(domain: string, id: number | string): Promise<void>;
143	  getDnsHosts(domain: string): Promise<DnsHost[]>;
144	
145	  // ---- URL forwarding ----
146	  listUrlForwarding(domain: string): Promise<UrlForward[]>;
147	  addUrlForwarding(domain: string, fwd: UrlForward): Promise<void>;
148	  deleteUrlForwarding(domain: string, host: string): Promise<void>;
149	}
