36	async function ownedDomain(domainId: string) {
37	  const user = await requireUser();
38	  const domain = await db.domain.findUnique({ where: { id: domainId } });
39	  if (!domain) throw new Error("Not found");
40	  if (domain.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
