51	/* A record shape the client can build for presets / imports. Host "" = apex. */
52	export type RecordInput = {
53	  host: string;
54	  type: string;
55	  answer: string;
56	  ttl?: number;
57	  priority?: number;
58	};
59	
60	const RECORD_TYPES = ["A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV", "ALIAS"] as const;
61	
62	function normHost(h: string): string {
63	  const t = (h ?? "").trim();
64	  return ["@", ""].includes(t) ? "" : t.replace(/\.$/, "");
65	}
66	
67	/** True if `want` is already present in `existing` (host+type+answer, MX also priority). */
68	function recordExists(existing: DnsRecord[], want: RecordInput): boolean {
69	  const wh = normHost(want.host);
70	  const wa = want.answer.trim().toLowerCase();
71	  return existing.some((r) => {
72	    if (r.host !== wh) return false;
73	    if (r.type !== want.type) return false;
74	    if (r.answer.trim().toLowerCase() !== wa) return false;
75	    if (want.type === "MX" && want.priority !== undefined) return (r.priority ?? 10) === want.priority;
76	    return true;
77	  });
78	}
79	
80	const recordInputSchema = z.object({
81	  host: z.string().max(120).default(""),
82	  type: z.enum(RECORD_TYPES),
83	  answer: z.string().min(1).max(2000),
84	  ttl: z.coerce.number().int().min(60).max(86400).default(300),
85	  priority: z.coerce.number().int().min(0).max(65535).optional(),
86	});
87	
88	export type BulkResult = {
89	  error?: string;
90	  added?: string[];
91	  skipped?: string[];
92	  failed?: { record: string; reason: string }[];
93	  note?: string;
94	};
95	
96	function label(r: RecordInput): string {
97	  const h = normHost(r.host) || "@";
98	  const pri = r.type === "MX" && r.priority !== undefined ? `${r.priority} ` : "";
99	  return `${r.type} ${h} → ${pri}${r.answer}`;
100	}
