171	/* ------------------------------------------------------------------ *
172	 * DNS import (paste) — CSV / zone-ish text: name,type,value[,ttl[,priority]]
173	 * Lines starting with # or ; are ignored. Whitespace or comma separated.
174	 * ------------------------------------------------------------------ */
175	
176	export type ParsedImport = { records: RecordInput[]; errors: string[] };
177	
178	/** Pure parser exported so the UI can preview before applying. */
179	export async function parseDnsImport(text: string): Promise<ParsedImport> {
180	  const records: RecordInput[] = [];
181	  const errors: string[] = [];
182	  const lines = (text ?? "").split(/\r?\n/);
183	  lines.forEach((line, i) => {
184	    const raw = line.trim();
185	    if (!raw || raw.startsWith("#") || raw.startsWith(";")) return;
186	    // split on comma OR whitespace, but keep the value token intact if quoted
187	    let parts: string[];
188	    if (raw.includes(",")) parts = raw.split(",").map((p) => p.trim());
189	    else parts = raw.split(/\s+/);
190	    if (parts.length < 3) {
191	      errors.push(`Line ${i + 1}: expected at least name, type, value`);
192	      return;
193	    }
194	    const [nameTok, typeTok, valueTok, ttlTok, prioTok] = parts;
195	    const type = typeTok.toUpperCase();
196	    if (!(RECORD_TYPES as readonly string[]).includes(type)) {
197	      errors.push(`Line ${i + 1}: unsupported type "${typeTok}"`);
198	      return;
199	    }
200	    const value = valueTok.replace(/^"|"$/g, "");
201	    const rec: RecordInput = { host: normHost(nameTok), type, answer: value };
202	    if (ttlTok && /^\d+$/.test(ttlTok)) rec.ttl = Math.min(86400, Math.max(60, Number(ttlTok)));
203	    if (type === "MX" && prioTok && /^\d+$/.test(prioTok)) rec.priority = Number(prioTok);
204	    records.push(rec);
205	  });
206	  return { records, errors };
207	}
208	
209	export async function importDnsRecords(domainId: string, text: string): Promise<BulkResult> {
210	  const { records, errors } = await parseDnsImport(text);
211	  if (errors.length && records.length === 0) {
212	    return { error: errors.join("; ").slice(0, 300) };
213	  }
214	  const res = await addDnsRecordsBulk(domainId, records);
215	  if (errors.length) {
216	    res.note = `${errors.length} line(s) skipped: ${errors.slice(0, 3).join("; ")}${errors.length > 3 ? "…" : ""}`;
217	  }
218	  return res;
219	}
