221	/* ------------------------------------------------------------------ *
222	 * Reset DNS to a sane default set (strong confirm handled in the UI).
223	 * Removes all customer-manageable records (A/AAAA/CNAME/TXT/MX/SRV/ALIAS),
224	 * leaves NS delegation untouched, then re-adds A @ / A www at the platform IP.
225	 * ------------------------------------------------------------------ */
226	
227	export async function resetDnsToDefaults(domainId: string): Promise<BulkResult> {
228	  let ctx;
229	  try {
230	    ctx = await ownedActiveDomain(domainId);
231	  } catch (e) {
232	    return { error: errMsg(e) };
233	  }
234	  const ip = process.env.PUBLIC_IP;
235	  const removable = new Set(["A", "AAAA", "CNAME", "TXT", "MX", "SRV", "ALIAS"]);
236	  let removed = 0;
237	  const failed: { record: string; reason: string }[] = [];
238	  try {
239	    const recs = await listRecords(ctx.domain.name);
240	    for (const r of recs) {
241	      if (!removable.has(r.type)) continue;
242	      try {
243	        await deleteRecord(ctx.domain.name, r.id);
244	        removed++;
245	      } catch (e) {
246	        failed.push({ record: `${r.type} ${r.host || "@"}`, reason: errMsg(e) });
247	      }
248	    }
249	  } catch (e) {
250	    return { error: `Could not read current records: ${errMsg(e)}` };
251	  }
252	
253	  const added: string[] = [];
254	  if (ip) {
255	    for (const host of ["", "www"]) {
256	      try {
257	        await addRecord(ctx.domain.name, { host, type: "A", answer: ip, ttl: 300 });
258	        added.push(`A ${host || "@"} → ${ip}`);
259	      } catch (e) {
260	        failed.push({ record: `A ${host || "@"}`, reason: errMsg(e) });
261	      }
262	    }
263	  }
264	
265	  await db.auditLog.create({
266	    data: { userId: ctx.user.id, action: "domain.dns_reset", detail: `${ctx.domain.name}: removed ${removed}, added ${added.length}` },
267	  });
268	  revalidatePath(`/dashboard/domains/${domainId}`);
269	  return {
270	    added,
271	    skipped: [],
272	    failed: failed.length ? failed : undefined,
273	    note: `Removed ${removed} record(s)${added.length ? ` and restored a default A record set pointing at ${ip}` : " (no platform IP configured, so no default records were added)"}.`,
274	  };
275	}
