332	export async function setRedirect(
333	  domainId: string,
334	  hostRaw: string,
335	  forwardsTo: string,
336	  type: string
337	): Promise<RedirectsView> {
338	  let ctx;
339	  try {
340	    ctx = await ownedDomain(domainId);
341	  } catch (e) {
342	    return { forwards: [], live: false, error: errMsg(e) };
343	  }
344	  const host = normHost(hostRaw);
345	  const t = (REDIRECT_TYPES as readonly string[]).includes(type) ? type : "redirect301";
346	  const url = z.string().url().max(2000).safeParse(forwardsTo.trim());
347	  if (!url.success) return { ...(await listRedirects(domainId)), error: "Enter a valid destination URL (including https://)." };
348	
349	  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
350	  if (canLive) {
351	    try {
352	      // Upsert: delete any existing forwarding for this host, then create.
353	      try {
354	        await deleteUrlForwarding(ctx.domain.name, host);
355	      } catch {
356	        /* none existed */
357	      }
358	      await addUrlForwarding(ctx.domain.name, { host, forwardsTo: url.data, type: t });
359	    } catch (e) {
360	      return { ...(await listRedirects(domainId)), error: `Registrar rejected the redirect: ${errMsg(e)}` };
361	    }
362	  } else {
363	    const list = (await readRedirectIntent(domainId)).filter((r) => normHost(r.host) !== host);
364	    list.push({ host, forwardsTo: url.data, type: t });
365	    await writeRedirectIntent(domainId, list);
366	  }
367	
368	  await db.auditLog.create({
369	    data: { userId: ctx.user.id, action: "domain.redirect_set", detail: `${ctx.domain.name} ${host || "@"} -> ${url.data} (${t})${canLive ? " live" : " intent"}` },
370	  });
371	  revalidatePath(`/dashboard/domains/${domainId}`);
372	  const view = await listRedirects(domainId);
373	  return {
374	    ...view,
375	    note: canLive
