555	export async function addUrlForwarding(domain: string, fwd: UrlForward): Promise<void> {
556	  const recordType = fwd.type === "redirect301" ? "URL301" : "URL";
557	  const existing = await listRecords(domain);
558	  const withoutSameHost = existing.filter((r) => !(isForwardRecord(r) && r.host === fwd.host));
