562	export async function deleteUrlForwarding(domain: string, host: string): Promise<void> {
563	  const existing = await listRecords(domain);
564	  const remaining = existing.filter((r) => !(isForwardRecord(r) && r.host === host));
565	  if (remaining.length === existing.length) return;
566	  await writeHosts(domain, remaining);
