78	export async function setupDomainInboxEmail(params: {
79	  userId: string;
80	  domainName: string;
81	  expiresAt: Date | null;
82	  /** Local-part the customer chose during registration, if any (e.g. "hello"). */
83	  mailboxLocalPart?: string | null;
84	}): Promise<void> {
85	  const { userId, domainName, expiresAt } = params;
86	  try {
87	    // Global dedup — one subscription per domain across ALL accounts, the same
88	    // guard every other EmailSubscription creator uses (2026-07-25 fix). A
89	    // fresh registration should never collide, but never double-grant either.
90	    const dupe = await db.emailSubscription.findFirst({
91	      where: { domainName, status: { not: "CANCELLED" } },
92	    });
93	    if (dupe) return;
94	
95	    const plan = await findDomainInboxPlan();
96	    if (!plan) {
97	      console.warn(`[domain-inbox-email] "${DOMAIN_INBOX_PLAN_NAME}" plan not seeded — skipping ${domainName}`);
98	      return;
99	    }
100	
101	    const sub = await db.emailSubscription.create({
102	      data: {
103	        userId,
104	        domainName,
105	        emailPlanId: plan.id,
106	        status: "ACTIVE",
107	        autoRenew: true,
108	        termMonths: 1,
109	        expiresAt,
110	        // In-account domain — we just registered it, so we control its DNS.
111	        // Treat as verified immediately, mirroring orderEmailHostingCore's
112	        // in-account branch (no DNS step for the customer to complete).
113	        external: false,
114	        verified: true,
115	        verifiedAt: new Date(),
116	        verifyToken: null,
117	      },
118	    });
119	
120	    await db.auditLog
121	      .create({
122	        data: {
123	          userId,
124	          action: "domain.freeinbox.setup",
125	          detail: `${domainName} · ${plan.name} (${plan.mailboxes} mailbox, ${plan.storageGB} GB)`,
126	        },
127	      })
128	      .catch(() => {});
129	
130	    const local = String(params.mailboxLocalPart ?? "")
131	      .trim()
132	      .toLowerCase();
133	    // No address chosen — reserved but mailbox-less, same "add it later" state
134	    // orderEmailHostingCore leaves every fresh subscription in.
135	    if (!local) return;
136	    // A malformed choice is skipped rather than failing the domain purchase —
137	    // the paid transaction already succeeded and must not be undone by a
138	    // cosmetic mailbox-name typo. The customer can add a valid one later.
139	    if (!localPartRe.test(local) || local.length > 64) {
140	      console.warn(`[domain-inbox-email] invalid local-part "${local}" for ${domainName} — left mailbox-less`);
141	      return;
142	    }
143	
144	    const address = `${local}@${domainName}`;
145	    // Mailbox.address is GLOBALLY unique (2026-07-25 fix) — a collision here
146	    // just means someone else already holds that exact address; leave this
147	    // subscription mailbox-less rather than fail the registration.
148	    const existingMailbox = await db.mailbox.findUnique({ where: { address } });
149	    if (existingMailbox) {
150	      console.warn(`[domain-inbox-email] ${address} already exists — left ${domainName}'s inbox mailbox-less`);
151	      return;
152	    }
153	
154	    const quotaMB = plan.storageGB * 1024;
155	    const mailbox = await db.mailbox.create({
156	      data: { subscriptionId: sub.id, address, quotaMB, status: "PROVISIONING" },
157	    });
158	
159	    if (!mailcowConfigured()) return; // left PROVISIONING, same as addMailbox()
160	
161	    try {
162	      if (!(await mcDomainExists(domainName))) {
163	        await mcCreateDomain(domainName).catch(() => {});
164	      }
165	      const password = randomBytes(18).toString("base64url");
166	      await mcCreateMailbox({ localPart: local, domain: domainName, name: address, password, quotaMB });
167	      await db.mailbox.update({
168	        where: { id: mailbox.id },
169	        data: { status: "ACTIVE", passwordEnc: encryptSecret(password) },
170	      });
171	    } catch (e) {
172	      await db.mailbox.update({ where: { id: mailbox.id }, data: { status: "FAILED" } }).catch(() => {});
