525	/**
526	 * A Cloudflare DNS API token safe to write into the certbot credentials file:
527	 * the exact charset Cloudflare mints (alnum plus `_`/`-`), length-bounded, and —
528	 * crucially — free of any shell/ini metacharacter. It lands in a file, not a
529	 * command, but an unvalidated secret never goes near a shell here, so we reject
530	 * anything outside this alphabet.
531	 */
532	const CF_TOKEN_RE = /^[A-Za-z0-9_-]{20,120}$/;
533	/** apt install of certbot + the DNS plugin, and a DNS-01 issuance (30s propagation
534	 *  wait built in), each run minutes — well past a single node STEP. */
535	const WILDCARD_STEP_MS = 5 * 60_000;
536	
537	/**
538	 * Mint (or renew) the ONE wildcard cert `*.<base>` (+ the apex `<base>`) via
539	 * certbot DNS-01 against Cloudflare on this node, so every free-subdomain site
540	 * gets INSTANT trusted HTTPS off a single Let's Encrypt lineage instead of a
541	 * per-subdomain HTTP-01 cert (slow AND capped at ~50 certs/week per registered
542	 * domain — a hard wall once signups scale).
543	 *
544	 * Fully opt-in + inert: does nothing unless hostingWildcardEnabled() (the
545	 * HOSTING_WILDCARD_SSL flag) AND a Cloudflare token is present AND shared hosting
546	 * is enabled AND not sandbox. Idempotent: `--keep-until-expiring` makes a run a
547	 * no-op until the cert is near expiry (so the ~daily cadence never churns LE), and
548	 * the credentials file is rewritten `600 root:root` each time. The token is
549	 * validated to a strict charset BEFORE it is ever written.
550	 */
551	export async function ensureWildcardCert(conn: Client): Promise<void> {
552	  if (SANDBOX || !ENABLED || !hostingWildcardEnabled()) return;
553	  const token = String(process.env.CLOUDFLARE_DNS_API_TOKEN ?? "").trim();
554	  if (!token) return; // no credential → silently skip (still inert)
555	  if (!CF_TOKEN_RE.test(token)) throw new Error("refusing unsafe CLOUDFLARE_DNS_API_TOKEN (charset)");
556	  const base = HOSTING_SUBDOMAIN_BASE;
557	  if (!isValidHostingDomain(base)) throw new Error(`refusing unsafe wildcard base ${base}`);
558	
559	  // 1. certbot + the Cloudflare DNS plugin — only installs when absent (idempotent).
560	  const inst = await exec(
561	    conn,
562	    `if ! command -v certbot >/dev/null 2>&1 || ! python3 -c 'import certbot_dns_cloudflare' >/dev/null 2>&1; then ` +
563	      `DEBIAN_FRONTEND=noninteractive apt-get update -qq && ` +
564	      `DEBIAN_FRONTEND=noninteractive apt-get install -y certbot python3-certbot-dns-cloudflare; fi`,
565	    WILDCARD_STEP_MS,
566	  );
567	  if (inst.code !== 0) throw new Error(`wildcard: certbot install failed: ${inst.out.slice(0, 200)}`);
568	
569	  // 2. Credentials file — root-only (600), written with umask so it is never even
570	  //    briefly world-readable. Token is validated to [A-Za-z0-9_-] so it is safe
571	  //    inside the single-quoted printf arg.
572	  const cred = await exec(
573	    conn,
574	    `mkdir -p /etc/letsencrypt && ( umask 077 && printf 'dns_cloudflare_api_token = %s\\n' '${token}' > /etc/letsencrypt/cloudflare.ini ) && ` +
575	      `chown root:root /etc/letsencrypt/cloudflare.ini && chmod 600 /etc/letsencrypt/cloudflare.ini`,
576	  );
577	  if (cred.code !== 0) throw new Error(`wildcard: writing cloudflare.ini failed: ${cred.out.slice(0, 200)}`);
578	
579	  // 3. Issue/renew the wildcard. --cert-name <base> pins the lineage so the live
580	  //    dir path (wildcardCertLiveDir) is stable; --keep-until-expiring no-ops until
581	  //    near expiry. `base` is a validated hostname ([a-z0-9.-]) so it is shell-inert.
582	  const issue = await exec(
583	    conn,
584	    `certbot certonly --dns-cloudflare --dns-cloudflare-credentials /etc/letsencrypt/cloudflare.ini ` +
585	      `--dns-cloudflare-propagation-seconds 30 -d '*.${base}' -d '${base}' --cert-name ${base} ` +
586	      `--non-interactive --agree-tos --register-unsafely-without-email --keep-until-expiring 2>&1`,
587	    WILDCARD_STEP_MS,
588	  );
589	  const liveDir = wildcardCertLiveDir();
590	  if (!(await fileExistsOnNode(conn, `${liveDir}/fullchain.pem`))) {
591	    throw new Error(`wildcard cert not present after issuance: ${issue.out.slice(-240)}`);
592	  }
593	  console.log(`[hosting] wildcard cert ready for *.${base} on node`);
594	}
